def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

def find_duplicates(lst):
    seen = set()
    return list({x for x in lst if x in seen or seen.add(x)})

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def max_subarray(arr):
    max_cur = max_glo = arr[0]
    for x in arr[1:]:
        max_cur = max(x, max_cur + x)
        max_glo = max(max_glo, max_cur)
    return max_glo
